import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Favoritos","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/favorites.md","filePath":"es-ES/user-guide/settings/favorites.md","lastUpdated":1785993908000}'),s={name:"es-ES/user-guide/settings/favorites.md"};function i(n,a,l,d,u,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="favoritos" tabindex="-1">Favoritos <a class="header-anchor" href="#favoritos" aria-label="Permalink to &quot;Favoritos&quot;">​</a></h1><p>Fija carpetas, archivos o URL de uso frecuente para que siempre estén a una pulsación de distancia.</p><h2 id="anadir-un-favorito" tabindex="-1">Añadir un favorito <a class="header-anchor" href="#anadir-un-favorito" aria-label="Permalink to &quot;Añadir un favorito&quot;">​</a></h2><ul><li><strong>Nombre para mostrar</strong> — opcional; si se deja en blanco y el destino es una ruta local, se rellena automáticamente a partir del nombre de archivo de la ruta.</li><li><strong>Ruta de destino</strong> — una ruta local, o una URL <code>http://</code>/<code>https://</code>.</li><li>Los botones <strong>Examinar carpeta</strong> / <strong>Examinar archivo</strong> abren un selector nativo en lugar de escribir la ruta.</li><li>Botón <strong>Añadir</strong> — se habilita en cuanto se introduce una ruta.</li></ul><h2 id="gestionar-la-lista" tabindex="-1">Gestionar la lista <a class="header-anchor" href="#gestionar-la-lista" aria-label="Permalink to &quot;Gestionar la lista&quot;">​</a></h2><p>Cada favorito de la lista muestra su nombre y ruta de destino, con acciones por fila:</p><ul><li><strong>Subir</strong> / <strong>Bajar</strong> — reordena la lista, lo que también afecta a cómo se clasifican los favoritos frente a otros resultados de búsqueda. Cada fila también se puede arrastrar directamente por el asa de seis puntos de su borde izquierdo — la misma asa de arrastrar-para-reordenar que usa cualquier otra lista reordenable de Configuración (Prioridad de tipo de resultado, Orden de Navegación rápida, Orden de filtros de la barra lateral, y Orden de columnas de la cuadrícula de resultados).</li><li><strong>Editar</strong> — vuelve a cargar el elemento en los campos de arriba para modificarlo.</li><li><strong>Eliminar</strong> — lo borra.</li></ul><h2 id="como-aparecen-los-favoritos-en-la-busqueda" tabindex="-1">Cómo aparecen los favoritos en la búsqueda <a class="header-anchor" href="#como-aparecen-los-favoritos-en-la-busqueda" aria-label="Permalink to &quot;Cómo aparecen los favoritos en la búsqueda&quot;">​</a></h2><p>Un favorito que coincida aparece en los resultados con una marca <strong>★</strong> junto a su etiqueta de carpeta/ruta, y se puede buscar por su nombre para mostrar — incluido en pinyin, si el nombre contiene caracteres chinos, igual que cualquier otro resultado. Este es el equivalente más cercano de Lertaro a un alias de búsqueda personalizado; ver <a href="./../search-syntax.html#favoritos-no-alias-personalizados">Sintaxis de búsqueda</a>.</p>',9)])])}const f=e(s,[["render",i]]);export{m as __pageData,f as default};
